/** Walk middlewares like Express: next(), next(err), throws, async, final 404. */
function compose(middlewares, errorHandler) {
  return async function app(req, res) {
    // Write your solution here
    for (const mw of middlewares) {
      await mw(req, res, () => {});
    }
  };
}

